// merge sees the children in their final shape.
const mergeStringChildren: DistillerPlugin = {
  name: 'mergeStringChildren',
  exit(node: aria.AriaNode) {
    const children: (aria.AriaNode | string)[] = [];
    const buffer: string[] = [];
    const flush = () => {
      if (!buffer.length)
